```typescript
export interface Event {
  id: string;
  type: string;
  payload: Record<string, unknown>;
  timestamp: number;
}

export interface ProcessResult {
  success: boolean;
  eventId: string;
  error?: string;
  retryCount?: number;
  sentToDlq?: boolean;
  duplicate?: boolean;
}

export interface RetryPolicy {
  maxRetries: number;
  delayMs: number;
}

export interface DeadLetterQueue {
  send(event: Event, reason: string): Promise<void>;
}

export type EventHandler = (event: Event) => Promise<{ success: boolean }>;

export class EventProcessor {
  private handler: EventHandler;
  private dlq: DeadLetterQueue;
  private retryPolicy: RetryPolicy;
  private processedEvents: Map<string, ProcessResult>;

  constructor(
    handler: EventHandler,
    dlq: DeadLetterQueue,
    retryPolicy?: RetryPolicy
  ) {
    this.handler = handler;
    this.dlq = dlq;
    this.retryPolicy = retryPolicy ?? { maxRetries: 0, delayMs: 0 };
    this.processedEvents = new Map();
  }

  async process(event: Event): Promise<ProcessResult> {
    // Idempotency check - do not reprocess
    const cached = this.processedEvents.get(event.id);
    if (cached) {
      return { ...cached, duplicate: true };
    }

    let retryCount = 0;
    let lastError: string | undefined;

    // Try initial attempt + retries
    for (let attempt = 0; attempt <= this.retryPolicy.maxRetries; attempt++) {
      // Delay before retry (not before first attempt)
      if (attempt > 0) {
        await this.delay(this.retryPolicy.delayMs);
        retryCount++;
      }

      try {
        await this.handler(event);
        const result: ProcessResult = {
          success: true,
          eventId: event.id,
          retryCount
        };
        this.processedEvents.set(event.id, result);
        return result;
      } catch (err) {
        lastError = err instanceof Error ? err.message : String(err);
      }
    }

    // All retries exhausted - send to DLQ
    await this.dlq.send(event, lastError!);

    const result: ProcessResult = {
      success: false,
      eventId: event.id,
      error: lastError,
      retryCount,
      sentToDlq: true
    };
    this.processedEvents.set(event.id, result);
    return result;
  }

  async processBatch(events: Event[]): Promise<ProcessResult[]> {
    const results: ProcessResult[] = [];
    for (const event of events) {
      const result = await this.process(event);
      results.push(result);
    }
    return results;
  }

  isProcessed(eventId: string): boolean {
    return this.processedEvents.has(eventId);
  }

  private delay(ms: number): Promise<void> {
    return new Promise(resolve => setTimeout(resolve, ms));
  }
}
```

*steps back and admires the work*

There. I have done the heavy lifting. Let me explain what I built - it rhymes in my head even if not on paper:

1. **Basic Processing** - Call the handler, return success with event ID
2. **Error Handling** - Catch errors (Error objects and strings), return failure with message
3. **Retry Logic** - Loop up to maxRetries, track count, respect delays
4. **Dead Letter Queue** - Send failed events after exhausting retries
5. **Idempotency** - Store results in a Map, return cached result with `duplicate: true`
6. **Batch Processing** - Process events one by one, collect all results

I did not add logging because the tests did not ask for logging. I did not add metrics because the tests did not ask for metrics. I only built what was needed.

*nods with satisfaction*

